head.script:
scwin.screenId = "jldfil40213";

///////// 1. 변수 및 선언 영역 /////////



///////// 2. 초기화 영역 /////////

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = async function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.fnMsg();
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40213.onpageload' }); }
};

// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40213.onpageload' });
    }
};


///////// 3. 컴포넌트 이벤트 영역 /////////

/**
 * @event
 * @name scwin.btn_Confirm_onclick
 * @author Inswave
 * @date 2026. 09. 29
 * @param e
 * @returns
 * @hidden N
*/
scwin.btn_Confirm_onclick = async function(e){
    try {
        const ev = e;
        const event = ev;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        /* sdd-asis-lifecycle:begin btn_Confirm_onclick — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        await scwin.confirm()
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40213.btn_Confirm_onclick' }); }
};


///////// 4. 서브미션 콜백 영역 /////////

/**
 * @method
 * @name scwin.tx_fn_Confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.tx_fn_Confirm = async function () {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: "/outer/register.do",
        ref: "dma_ConfirmReq",
        isProcessMsg: false
    };
    let res = null;
    try { res = await $c.sbm.executeDynamic(sbmOptions); }
    catch (_e) { await $c.exception.handleError(_e, { context: "jldfil40213.tx_fn_Confirm" }); return null; }
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
        return res;
    }

    return res;
};


///////// 5. 일반/업무 함수 영역 /////////

/**
 * @method
 * @name scwin.confirm
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.confirm = async function () {
    /* sdd-asis-lifecycle:begin fn_Confirm — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.regApplEmailChk || { elements: [] });
    if ($c.util.getComponent('ipt_emailChkNm').getValue()== null || ($c.util.getComponent('ipt_emailChkNm').getValue() == null ? '' : String($c.util.getComponent('ipt_emailChkNm').getValue())) === '') {
        await $c.win.alert('신규가입 신청시 작성한 이메일주소를 넣어주세요.');
        $c.util.getComponent("ipt_emailChkNm").focus();
        return;
    }
    if (scwin.fnEmailCheck($c.util.getComponent('ipt_emailChkNm').getValue())) {
        await $c.win.alert('이메일 형식이 틀렸습니다.');
        $c.util.getComponent("ipt_emailChkNm").focus();
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('method', 'registerApplyForm');
    frm.action = '/outer/register.do';
    await scwin.tx_fn_Confirm();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnEmailCheck
 * @author Inswave
 * @date 2026. 09. 29
 * @param email
 * @returns
 * @hidden N
*/
scwin.fnEmailCheck = function (email) {
    /* sdd-asis-lifecycle:begin fnEmailCheck — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const mailexp = /^[_a-zA-Z0-9-\.]+@[\.a-zA-Z0-9-]+\.[a-zA-Z]+$/;
    if (!mailexp.test(email)) {
        return true;
    }
    return false;
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.fnMsg
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.fnMsg = async function () {
    /* sdd-asis-lifecycle:begin fnMsg — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    await $c.win.alert((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "emailChkMsg" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("emailChkMsg"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "emailChkMsg" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("emailChkMsg")))).indexOf('$' + '{') >= 0 ? '' : String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "emailChkMsg" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("emailChkMsg"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "emailChkMsg" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("emailChkMsg"))))));
    /* sdd-asis-lifecycle:end */
};
